"""Storage helpers for unlisted, expiring result previews."""
from __future__ import annotations

from datetime import datetime, timezone
import json
import re
import secrets
import time
from pathlib import Path


PREVIEW_RETENTION_SECONDS = 7 * 24 * 60 * 60
_PREVIEW_ID = re.compile(r"^[A-Za-z0-9_-]{40,60}$")


def new_preview_id() -> str:
    """Return a high-entropy URL-safe bearer identifier."""
    return secrets.token_urlsafe(32)


def preview_paths(output_folder, preview_id):
    """Resolve paths only for identifiers generated by this module."""
    if not isinstance(preview_id, str) or not _PREVIEW_ID.fullmatch(preview_id):
        return None
    folder = Path(output_folder) / "previews"
    return folder, folder / f"{preview_id}.mp4", folder / f"{preview_id}.json"


def cleanup_expired_previews(folder, *, now=None):
    """Remove expired preview files and metadata from the managed folder."""
    folder = Path(folder)
    now = time.time() if now is None else float(now)
    folder.mkdir(parents=True, exist_ok=True)
    for metadata_path in folder.glob("*.json"):
        preview_id = metadata_path.stem
        paths = preview_paths(folder.parent, preview_id)
        if paths is None:
            continue
        try:
            metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
            expires_at = float(metadata.get("expires_at", 0))
        except (OSError, ValueError, TypeError):
            expires_at = 0
        if expires_at <= now:
            metadata_path.unlink(missing_ok=True)
            (folder / f"{preview_id}.mp4").unlink(missing_ok=True)
    return folder


def load_preview(output_folder, preview_id, *, now=None):
    """Load a valid, unexpired preview record, or return None."""
    paths = preview_paths(output_folder, preview_id)
    if paths is None:
        return None
    folder, video_path, metadata_path = paths
    now = time.time() if now is None else float(now)
    try:
        metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
        expires_at = float(metadata.get("expires_at", 0))
        if (metadata.get("id") != preview_id or expires_at <= now
                or not video_path.is_file() or video_path.stat().st_size < 1024):
            if expires_at <= now:
                metadata_path.unlink(missing_ok=True)
                video_path.unlink(missing_ok=True)
            return None
        return metadata
    except (OSError, ValueError, TypeError):
        return None


def write_preview_metadata(metadata_path, metadata):
    """Atomically persist a JSON preview record without exposing it publicly."""
    metadata_path = Path(metadata_path)
    def json_safe(value):
        if isinstance(value, Path):
            return str(value)
        if isinstance(value, dict):
            return {str(key): json_safe(item) for key, item in value.items()}
        if isinstance(value, (list, tuple)):
            return [json_safe(item) for item in value]
        if value is None or isinstance(value, (str, int, float, bool)):
            return value
        raise TypeError(f"Unsupported preview setting type: {type(value).__name__}")

    encoded = json.dumps(json_safe(metadata), ensure_ascii=False, separators=(",", ":"))
    if len(encoded.encode("utf-8")) > 8 * 1024 * 1024:
        raise ValueError("Preview settings are too large to save safely.")
    temporary_path = metadata_path.with_suffix(".json.tmp")
    temporary_path.write_text(encoded, encoding="utf-8")
    temporary_path.replace(metadata_path)


def utc_timestamp(epoch_seconds):
    return datetime.fromtimestamp(epoch_seconds, timezone.utc).isoformat()
